create table if not exists public.office_threads (id uuid primary key default gen_random_uuid(), subject text not null, customer_email text, order_id uuid references public.orders(id) on delete set null, status text not null default 'open' check(status in ('open','closed')), created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.office_messages (id uuid primary key default gen_random_uuid(), thread_id uuid not null references public.office_threads(id) on delete cascade, author_id uuid references auth.users(id) on delete set null, kind text not null default 'internal' check(kind in ('internal','note','email_in','email_out')), body text not null, created_at timestamptz not null default now());
create table if not exists public.office_tasks (id uuid primary key default gen_random_uuid(), thread_id uuid references public.office_threads(id) on delete cascade, title text not null, status text not null default 'open' check(status in ('open','done','cancelled')), assigned_to uuid references auth.users(id) on delete set null, due_at timestamptz, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), completed_at timestamptz);
create index if not exists office_threads_updated_idx on public.office_threads(updated_at desc);create index if not exists office_messages_thread_idx on public.office_messages(thread_id,created_at);create index if not exists office_tasks_status_idx on public.office_tasks(status,due_at);
alter table public.office_threads enable row level security;alter table public.office_messages enable row level security;alter table public.office_tasks enable row level security;
create policy "admins manage office threads" on public.office_threads for all to authenticated using (exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check (exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create policy "admins manage office messages" on public.office_messages for all to authenticated using (exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check (exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create policy "admins manage office tasks" on public.office_tasks for all to authenticated using (exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check (exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
